                queue.append(nxt)

    visited = [False] * len(adj)
    dfs = []

    def visit(node):
        visited[node] = True
        dfs.append(node)
        for nxt in adj[node]:
            if not visited[nxt]:
                visit(nxt)

    visit(0)
    return [bfs, dfs]

